#include <stack>
#include <iostream>

int main() {
    std::stack<int> sA;
    sA.push(10); sA.push(20); 

    std::stack<int> sB;
    sB.push(10); sB.push(30); 

    std::stack<int> sC;
    sC.push(10); sC.push(20); sC.push(5); 

    // sA < sB: True (20 < 30 at the top element)
    std::cout << (sA < sB) << std::endl; 

    // sA < sC: True (sA is a prefix of sC)
    std::cout << (sA < sC) << std::endl; 
}
